import { bindOneShotAnimation, unpackAnimationClips } from './packed-animation.js';

let clips;
export function bindPunchAnimation(entity) {
  if (entity.actions.has(PUNCH_ANIMATION.name)) return;
  clips ??= unpackAnimationClips(PACKED_PUNCH_CLIPS);
  const clip = clips.get(`${PUNCH_ANIMATION.name}_${entity.modelSex}`);
  bindOneShotAnimation(entity, PUNCH_ANIMATION.name, clip);
}

// Punch animation data generated by scripts/prepare-punch-animations.mjs.
export const PUNCH_ANIMATION = {"name":"Punch_OneTwo","duration":1.3799999952316284};
const PACKED_PUNCH_CLIPS = "";
